package com.immersio.scenarios.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="\"ScenarioSessions\"") public class ScenarioSession { @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="\"Id\"") private UUID id; @Column(name="\"UserId\"") private UUID userId; @Column(name="\"ScenarioId\"") private UUID scenarioId; @Column(name="\"StartedAt\"") private Instant startedAt=Instant.now(); @Column(name="\"FinishedAt\"") private Instant finishedAt; @Column(name="\"Feedback\"") private String feedback; @Column(name="\"IsFinished\"") private boolean finished; protected ScenarioSession(){} public ScenarioSession(UUID u,UUID s){userId=u;scenarioId=s;} public UUID getId(){return id;} public UUID getUserId(){return userId;} public UUID getScenarioId(){return scenarioId;} public Instant getStartedAt(){return startedAt;} public Instant getFinishedAt(){return finishedAt;} public String getFeedback(){return feedback;} public boolean isFinished(){return finished;} public void finish(String f){finished=true;feedback=f;finishedAt=Instant.now();} }
